-- V1__schema.sql
-- Baseline schema of the Sigyll certificate request portal database (PortalDbContext, including
-- its ASP.NET Core Identity tables). Generated from the EF Core model on 2026-10-22, when schema
-- ownership moved from EF migrations to Flyway; later changes are new V files. Identifiers are
-- quoted PascalCase to match the EF Core model. Privileges live in V0__schema_privileges.sql.

CREATE TABLE "AspNetRoles" (
    "Id" TEXT NOT NULL,
    "Name" CHARACTER VARYING(256),
    "NormalizedName" CHARACTER VARYING(256),
    "ConcurrencyStamp" TEXT,
    CONSTRAINT "PK_AspNetRoles" PRIMARY KEY ("Id")
);

COMMENT ON TABLE "AspNetRoles" IS 'ASP.NET Core Identity roles';

COMMENT ON COLUMN "AspNetRoles"."Id" IS 'Primary key (role id)';

COMMENT ON COLUMN "AspNetRoles"."Name" IS 'Role name';

COMMENT ON COLUMN "AspNetRoles"."NormalizedName" IS 'Upper-cased role name used for lookups';

COMMENT ON COLUMN "AspNetRoles"."ConcurrencyStamp" IS 'Random value that changes on every update (optimistic concurrency)';

CREATE TABLE "AspNetUsers" (
    "Id" TEXT NOT NULL,
    "DisplayName" TEXT,
    "OrganizationId" INTEGER,
    "ProofingStatus" INTEGER NOT NULL,
    "UserName" CHARACTER VARYING(256),
    "NormalizedUserName" CHARACTER VARYING(256),
    "Email" CHARACTER VARYING(256),
    "NormalizedEmail" CHARACTER VARYING(256),
    "EmailConfirmed" BOOLEAN NOT NULL,
    "PasswordHash" TEXT,
    "SecurityStamp" TEXT,
    "ConcurrencyStamp" TEXT,
    "PhoneNumber" CHARACTER VARYING(256),
    "PhoneNumberConfirmed" BOOLEAN NOT NULL,
    "TwoFactorEnabled" BOOLEAN NOT NULL,
    "LockoutEnd" TIMESTAMP WITH TIME ZONE,
    "LockoutEnabled" BOOLEAN NOT NULL,
    "AccessFailedCount" INTEGER NOT NULL,
    CONSTRAINT "PK_AspNetUsers" PRIMARY KEY ("Id")
);

COMMENT ON TABLE "AspNetUsers" IS 'ASP.NET Core Identity user accounts for the certificate request portal';

COMMENT ON COLUMN "AspNetUsers"."Id" IS 'Primary key (user id)';

COMMENT ON COLUMN "AspNetUsers"."DisplayName" IS 'Name shown in the UI';

COMMENT ON COLUMN "AspNetUsers"."OrganizationId" IS 'Organization the user belongs to (Organizations.Id); null until assigned';

COMMENT ON COLUMN "AspNetUsers"."ProofingStatus" IS 'Identity proofing state: 0 Unverified, 1 Pending, 2 Verified, 3 Rejected';

COMMENT ON COLUMN "AspNetUsers"."UserName" IS 'Sign-in name';

COMMENT ON COLUMN "AspNetUsers"."NormalizedUserName" IS 'Upper-cased user name used for lookups';

COMMENT ON COLUMN "AspNetUsers"."Email" IS 'Email address';

COMMENT ON COLUMN "AspNetUsers"."NormalizedEmail" IS 'Upper-cased email used for lookups';

COMMENT ON COLUMN "AspNetUsers"."EmailConfirmed" IS 'Whether the email address has been confirmed';

COMMENT ON COLUMN "AspNetUsers"."PasswordHash" IS 'Salted and hashed password; null for passwordless (passkey-only) accounts';

COMMENT ON COLUMN "AspNetUsers"."SecurityStamp" IS 'Random value that changes when credentials change; invalidates existing sign-ins';

COMMENT ON COLUMN "AspNetUsers"."ConcurrencyStamp" IS 'Random value that changes on every update (optimistic concurrency)';

COMMENT ON COLUMN "AspNetUsers"."PhoneNumber" IS 'Phone number';

COMMENT ON COLUMN "AspNetUsers"."PhoneNumberConfirmed" IS 'Whether the phone number has been confirmed';

COMMENT ON COLUMN "AspNetUsers"."TwoFactorEnabled" IS 'Whether two-factor sign-in is enabled';

COMMENT ON COLUMN "AspNetUsers"."LockoutEnd" IS 'When an active lockout ends; null when not locked out';

COMMENT ON COLUMN "AspNetUsers"."LockoutEnabled" IS 'Whether the account can be locked out after failed sign-ins';

COMMENT ON COLUMN "AspNetUsers"."AccessFailedCount" IS 'Consecutive failed sign-in attempts';

CREATE TABLE "CertificateRequests" (
    "Id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "RequesterId" TEXT NOT NULL,
    "OrganizationId" INTEGER,
    "TrustDomainName" TEXT NOT NULL,
    "ProfileName" TEXT NOT NULL,
    "SubjectDn" TEXT NOT NULL,
    "RequestedSansJson" TEXT,
    "CsrPem" TEXT NOT NULL,
    "Status" INTEGER NOT NULL,
    "PolicyDecision" INTEGER,
    "PolicyReason" TEXT,
    "ValidationMethod" TEXT,
    "RaApproverId" TEXT,
    "RaReason" TEXT,
    "RaDecisionAt" TIMESTAMP WITH TIME ZONE,
    "RaApprovalRef" TEXT,
    "SerialNumber" TEXT,
    "Thumbprint" TEXT,
    "CertificatePem" TEXT,
    "ChainPem" TEXT,
    "FailureReason" TEXT,
    "CreatedAt" TIMESTAMP WITH TIME ZONE NOT NULL,
    "UpdatedAt" TIMESTAMP WITH TIME ZONE NOT NULL,
    "SubmittedAt" TIMESTAMP WITH TIME ZONE,
    "IssuedAt" TIMESTAMP WITH TIME ZONE,
    CONSTRAINT "PK_CertificateRequests" PRIMARY KEY ("Id")
);

COMMENT ON TABLE "CertificateRequests" IS 'Certificate requests submitted through the portal and their workflow state';

COMMENT ON COLUMN "CertificateRequests"."Id" IS 'Primary key';

COMMENT ON COLUMN "CertificateRequests"."RequesterId" IS 'Submitting user (AspNetUsers.Id)';

COMMENT ON COLUMN "CertificateRequests"."OrganizationId" IS 'Requesting organization (Organizations.Id)';

COMMENT ON COLUMN "CertificateRequests"."TrustDomainName" IS 'Trust domain the certificate is requested from';

COMMENT ON COLUMN "CertificateRequests"."ProfileName" IS 'Certificate profile requested';

COMMENT ON COLUMN "CertificateRequests"."SubjectDn" IS 'Subject distinguished name requested';

COMMENT ON COLUMN "CertificateRequests"."RequestedSansJson" IS 'Requested subject alternative names as JSON';

COMMENT ON COLUMN "CertificateRequests"."CsrPem" IS 'PKCS#10 request, PEM encoded';

COMMENT ON COLUMN "CertificateRequests"."Status" IS '0 Draft, 1 Submitted, 2 PolicyEvaluated, 3 PendingValidation, 4 Validated, 5 PendingRaApproval, 6 Approved, 7 Rejected, 8 Issuing, 9 Issued, 10 Failed, 11 Closed';

COMMENT ON COLUMN "CertificateRequests"."PolicyDecision" IS '0 AutoIssue, 1 RequiresRaApproval; null until evaluated';

COMMENT ON COLUMN "CertificateRequests"."PolicyReason" IS 'Why the policy decided as it did';

COMMENT ON COLUMN "CertificateRequests"."ValidationMethod" IS 'How domain control was proven, e.g. http-01 or dns-01';

COMMENT ON COLUMN "CertificateRequests"."RaApproverId" IS 'RA officer who decided (AspNetUsers.Id)';

COMMENT ON COLUMN "CertificateRequests"."RaReason" IS 'RA officer''s reason for the decision';

COMMENT ON COLUMN "CertificateRequests"."RaDecisionAt" IS 'When the RA officer decided (UTC)';

COMMENT ON COLUMN "CertificateRequests"."RaApprovalRef" IS 'Approval reference passed to the CA issuance API';

COMMENT ON COLUMN "CertificateRequests"."SerialNumber" IS 'Serial number of the issued certificate, hex';

COMMENT ON COLUMN "CertificateRequests"."Thumbprint" IS 'Thumbprint of the issued certificate';

COMMENT ON COLUMN "CertificateRequests"."CertificatePem" IS 'Issued certificate, PEM encoded';

COMMENT ON COLUMN "CertificateRequests"."ChainPem" IS 'Issuing CA chain, PEM encoded';

COMMENT ON COLUMN "CertificateRequests"."FailureReason" IS 'Why issuance failed';

COMMENT ON COLUMN "CertificateRequests"."CreatedAt" IS 'When the request was created (UTC)';

COMMENT ON COLUMN "CertificateRequests"."UpdatedAt" IS 'When the request last changed (UTC)';

COMMENT ON COLUMN "CertificateRequests"."SubmittedAt" IS 'When the request was submitted (UTC)';

COMMENT ON COLUMN "CertificateRequests"."IssuedAt" IS 'When the certificate was issued (UTC)';

CREATE TABLE "Organizations" (
    "Id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "Name" TEXT NOT NULL,
    "ValidatedDomains" TEXT,
    "AuthorizedTrustDomains" TEXT,
    "Enabled" BOOLEAN NOT NULL,
    "CreatedAt" TIMESTAMP WITH TIME ZONE NOT NULL,
    CONSTRAINT "PK_Organizations" PRIMARY KEY ("Id")
);

COMMENT ON TABLE "Organizations" IS 'Organizations that request certificates through the portal';

COMMENT ON COLUMN "Organizations"."Id" IS 'Primary key';

COMMENT ON COLUMN "Organizations"."Name" IS 'Organization name';

COMMENT ON COLUMN "Organizations"."ValidatedDomains" IS 'Semicolon-delimited domains the organization has proven control of';

COMMENT ON COLUMN "Organizations"."AuthorizedTrustDomains" IS 'Semicolon-delimited trust domain names the organization may request from';

COMMENT ON COLUMN "Organizations"."Enabled" IS 'Whether the organization may submit requests';

COMMENT ON COLUMN "Organizations"."CreatedAt" IS 'When the organization was created (UTC)';

CREATE TABLE "AspNetRoleClaims" (
    "Id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "RoleId" TEXT NOT NULL,
    "ClaimType" TEXT,
    "ClaimValue" TEXT,
    CONSTRAINT "PK_AspNetRoleClaims" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_AspNetRoleClaims_AspNetRoles_RoleId" FOREIGN KEY ("RoleId") REFERENCES "AspNetRoles" ("Id") ON DELETE CASCADE
);

COMMENT ON TABLE "AspNetRoleClaims" IS 'Claims granted to every member of a role';

COMMENT ON COLUMN "AspNetRoleClaims"."Id" IS 'Primary key';

COMMENT ON COLUMN "AspNetRoleClaims"."RoleId" IS 'Role the claim belongs to (AspNetRoles.Id)';

COMMENT ON COLUMN "AspNetRoleClaims"."ClaimType" IS 'Claim type';

COMMENT ON COLUMN "AspNetRoleClaims"."ClaimValue" IS 'Claim value';

CREATE TABLE "AspNetUserClaims" (
    "Id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "UserId" TEXT NOT NULL,
    "ClaimType" TEXT,
    "ClaimValue" TEXT,
    CONSTRAINT "PK_AspNetUserClaims" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_AspNetUserClaims_AspNetUsers_UserId" FOREIGN KEY ("UserId") REFERENCES "AspNetUsers" ("Id") ON DELETE CASCADE
);

COMMENT ON TABLE "AspNetUserClaims" IS 'Claims held by a user';

COMMENT ON COLUMN "AspNetUserClaims"."Id" IS 'Primary key';

COMMENT ON COLUMN "AspNetUserClaims"."UserId" IS 'User the claim belongs to (AspNetUsers.Id)';

COMMENT ON COLUMN "AspNetUserClaims"."ClaimType" IS 'Claim type';

COMMENT ON COLUMN "AspNetUserClaims"."ClaimValue" IS 'Claim value';

CREATE TABLE "AspNetUserLogins" (
    "LoginProvider" CHARACTER VARYING(128) NOT NULL,
    "ProviderKey" CHARACTER VARYING(128) NOT NULL,
    "ProviderDisplayName" TEXT,
    "UserId" TEXT NOT NULL,
    CONSTRAINT "PK_AspNetUserLogins" PRIMARY KEY ("LoginProvider", "ProviderKey"),
    CONSTRAINT "FK_AspNetUserLogins_AspNetUsers_UserId" FOREIGN KEY ("UserId") REFERENCES "AspNetUsers" ("Id") ON DELETE CASCADE
);

COMMENT ON TABLE "AspNetUserLogins" IS 'External sign-in providers linked to a user';

COMMENT ON COLUMN "AspNetUserLogins"."LoginProvider" IS 'External provider name, e.g. Microsoft or Google';

COMMENT ON COLUMN "AspNetUserLogins"."ProviderKey" IS 'The user''s identifier at the external provider';

COMMENT ON COLUMN "AspNetUserLogins"."ProviderDisplayName" IS 'Provider name shown in the UI';

COMMENT ON COLUMN "AspNetUserLogins"."UserId" IS 'Linked user (AspNetUsers.Id)';

CREATE TABLE "AspNetUserPasskeys" (
    "CredentialId" BYTEA NOT NULL,
    "UserId" TEXT NOT NULL,
    "Data" JSONB NOT NULL,
    CONSTRAINT "PK_AspNetUserPasskeys" PRIMARY KEY ("CredentialId"),
    CONSTRAINT "FK_AspNetUserPasskeys_AspNetUsers_UserId" FOREIGN KEY ("UserId") REFERENCES "AspNetUsers" ("Id") ON DELETE CASCADE
);

COMMENT ON TABLE "AspNetUserPasskeys" IS 'WebAuthn passkeys registered to a user';

COMMENT ON COLUMN "AspNetUserPasskeys"."CredentialId" IS 'WebAuthn credential id (primary key)';

COMMENT ON COLUMN "AspNetUserPasskeys"."UserId" IS 'Owning user (AspNetUsers.Id)';

COMMENT ON COLUMN "AspNetUserPasskeys"."Data" IS 'Passkey public key and metadata as JSON';

CREATE TABLE "AspNetUserRoles" (
    "UserId" TEXT NOT NULL,
    "RoleId" TEXT NOT NULL,
    CONSTRAINT "PK_AspNetUserRoles" PRIMARY KEY ("UserId", "RoleId"),
    CONSTRAINT "FK_AspNetUserRoles_AspNetRoles_RoleId" FOREIGN KEY ("RoleId") REFERENCES "AspNetRoles" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_AspNetUserRoles_AspNetUsers_UserId" FOREIGN KEY ("UserId") REFERENCES "AspNetUsers" ("Id") ON DELETE CASCADE
);

COMMENT ON TABLE "AspNetUserRoles" IS 'Role membership of users';

COMMENT ON COLUMN "AspNetUserRoles"."UserId" IS 'Member (AspNetUsers.Id)';

COMMENT ON COLUMN "AspNetUserRoles"."RoleId" IS 'Role (AspNetRoles.Id)';

CREATE TABLE "AspNetUserTokens" (
    "UserId" TEXT NOT NULL,
    "LoginProvider" CHARACTER VARYING(128) NOT NULL,
    "Name" CHARACTER VARYING(128) NOT NULL,
    "Value" TEXT,
    CONSTRAINT "PK_AspNetUserTokens" PRIMARY KEY ("UserId", "LoginProvider", "Name"),
    CONSTRAINT "FK_AspNetUserTokens_AspNetUsers_UserId" FOREIGN KEY ("UserId") REFERENCES "AspNetUsers" ("Id") ON DELETE CASCADE
);

COMMENT ON TABLE "AspNetUserTokens" IS 'Tokens stored for a user, e.g. authenticator keys and recovery codes';

COMMENT ON COLUMN "AspNetUserTokens"."UserId" IS 'Owning user (AspNetUsers.Id)';

COMMENT ON COLUMN "AspNetUserTokens"."LoginProvider" IS 'Provider that issued the token';

COMMENT ON COLUMN "AspNetUserTokens"."Name" IS 'Token name';

COMMENT ON COLUMN "AspNetUserTokens"."Value" IS 'Token value';

CREATE TABLE "DomainValidationChallenges" (
    "Id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "RequestId" INTEGER NOT NULL,
    "Identifier" TEXT NOT NULL,
    "Token" TEXT NOT NULL,
    "KeyAuthorization" TEXT NOT NULL,
    "Status" INTEGER NOT NULL,
    "Attempts" INTEGER NOT NULL,
    "CreatedAt" TIMESTAMP WITH TIME ZONE NOT NULL,
    "VerifiedAt" TIMESTAMP WITH TIME ZONE,
    CONSTRAINT "PK_DomainValidationChallenges" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_DomainValidationChallenges_CertificateRequests_RequestId" FOREIGN KEY ("RequestId") REFERENCES "CertificateRequests" ("Id") ON DELETE CASCADE
);

COMMENT ON TABLE "DomainValidationChallenges" IS 'Domain-control challenges for a certificate request';

COMMENT ON COLUMN "DomainValidationChallenges"."Id" IS 'Primary key';

COMMENT ON COLUMN "DomainValidationChallenges"."RequestId" IS 'Certificate request (CertificateRequests.Id)';

COMMENT ON COLUMN "DomainValidationChallenges"."Identifier" IS 'Domain name being validated';

COMMENT ON COLUMN "DomainValidationChallenges"."Token" IS 'Challenge token';

COMMENT ON COLUMN "DomainValidationChallenges"."KeyAuthorization" IS 'Expected key authorization the domain must serve';

COMMENT ON COLUMN "DomainValidationChallenges"."Status" IS '0 Pending, 1 Valid, 2 Invalid';

COMMENT ON COLUMN "DomainValidationChallenges"."Attempts" IS 'Number of verification attempts';

COMMENT ON COLUMN "DomainValidationChallenges"."CreatedAt" IS 'When the challenge was created (UTC)';

COMMENT ON COLUMN "DomainValidationChallenges"."VerifiedAt" IS 'When the challenge passed (UTC)';

CREATE TABLE "RequestEvents" (
    "Id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "RequestId" INTEGER NOT NULL,
    "Actor" TEXT NOT NULL,
    "EventType" TEXT NOT NULL,
    "Detail" TEXT,
    "At" TIMESTAMP WITH TIME ZONE NOT NULL,
    CONSTRAINT "PK_RequestEvents" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_RequestEvents_CertificateRequests_RequestId" FOREIGN KEY ("RequestId") REFERENCES "CertificateRequests" ("Id") ON DELETE CASCADE
);

COMMENT ON TABLE "RequestEvents" IS 'Audit trail of a certificate request';

COMMENT ON COLUMN "RequestEvents"."Id" IS 'Primary key';

COMMENT ON COLUMN "RequestEvents"."RequestId" IS 'Certificate request (CertificateRequests.Id)';

COMMENT ON COLUMN "RequestEvents"."Actor" IS 'Who acted: a user id or system';

COMMENT ON COLUMN "RequestEvents"."EventType" IS 'What happened, e.g. Submitted, Approved, Issued';

COMMENT ON COLUMN "RequestEvents"."Detail" IS 'Event details';

COMMENT ON COLUMN "RequestEvents"."At" IS 'When it happened (UTC)';

CREATE TABLE "OrganizationMemberships" (
    "Id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "OrganizationId" INTEGER NOT NULL,
    "UserId" TEXT NOT NULL,
    "Role" INTEGER NOT NULL,
    "CreatedAt" TIMESTAMP WITH TIME ZONE NOT NULL,
    CONSTRAINT "PK_OrganizationMemberships" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_OrganizationMemberships_Organizations_OrganizationId" FOREIGN KEY ("OrganizationId") REFERENCES "Organizations" ("Id") ON DELETE CASCADE
);

COMMENT ON TABLE "OrganizationMemberships" IS 'Users belonging to an organization';

COMMENT ON COLUMN "OrganizationMemberships"."Id" IS 'Primary key';

COMMENT ON COLUMN "OrganizationMemberships"."OrganizationId" IS 'Organization (Organizations.Id)';

COMMENT ON COLUMN "OrganizationMemberships"."UserId" IS 'Member (AspNetUsers.Id)';

COMMENT ON COLUMN "OrganizationMemberships"."Role" IS '0 Member, 1 Admin';

COMMENT ON COLUMN "OrganizationMemberships"."CreatedAt" IS 'When the membership was created (UTC)';

CREATE INDEX "IX_AspNetRoleClaims_RoleId" ON "AspNetRoleClaims" ("RoleId");

CREATE UNIQUE INDEX "RoleNameIndex" ON "AspNetRoles" ("NormalizedName");

CREATE INDEX "IX_AspNetUserClaims_UserId" ON "AspNetUserClaims" ("UserId");

CREATE INDEX "IX_AspNetUserLogins_UserId" ON "AspNetUserLogins" ("UserId");

CREATE INDEX "IX_AspNetUserPasskeys_UserId" ON "AspNetUserPasskeys" ("UserId");

CREATE INDEX "IX_AspNetUserRoles_RoleId" ON "AspNetUserRoles" ("RoleId");

CREATE INDEX "EmailIndex" ON "AspNetUsers" ("NormalizedEmail");

CREATE UNIQUE INDEX "UserNameIndex" ON "AspNetUsers" ("NormalizedUserName");

CREATE INDEX "IX_CertificateRequests_RequesterId" ON "CertificateRequests" ("RequesterId");

CREATE INDEX "IX_CertificateRequests_Status" ON "CertificateRequests" ("Status");

CREATE INDEX "IX_DomainValidationChallenges_RequestId" ON "DomainValidationChallenges" ("RequestId");

CREATE INDEX "IX_DomainValidationChallenges_Token" ON "DomainValidationChallenges" ("Token");

CREATE UNIQUE INDEX "IX_OrganizationMemberships_OrganizationId_UserId" ON "OrganizationMemberships" ("OrganizationId", "UserId");

CREATE INDEX "IX_OrganizationMemberships_UserId" ON "OrganizationMemberships" ("UserId");

CREATE INDEX "IX_RequestEvents_RequestId" ON "RequestEvents" ("RequestId");
